<?php
if(getenv('EMSF_DISPOSABLE_TEST')!=='yes'||!str_contains(ABSPATH,'emsf-integration')){throw new RuntimeException('Disposable test only');}
require_once dirname(__DIR__).'/emonks-site-factory.php';
use Emonks\Factory\Package;
use Emonks\Factory\Online\{Receiver,Store,ContentChanges,Accounts,Preview,Admin,Activity,MailDraft};
wp_set_current_user(1);$n=0;
$check=static function($ok,$label)use(&$n){if(!$ok){throw new RuntimeException('FAIL: '.$label);}++$n;echo "PASS: $label\n";};
$reject=static function(callable $fn,string $label)use($check){try{$fn();}catch(RuntimeException $e){$check(true,$label);return;}throw new LogicException('Accepted: '.$label);};
$req=static function($data){$r=new WP_REST_Request('POST');$r->set_header('Content-Type','application/json');$r->set_body(wp_json_encode($data));return $r;};
