$manifest=['format'=>Package::FORMAT,'version'=>1,'theme'=>'skeletor','prospect'=>['uuid'=>$source,'name'=>'Optional '.$short],'dependencies'=>['theme_version'=>wp_get_theme('skeletor')->get('Version'),'theme_digest'=>Package::theme_digest()],'unsupported'=>[],'models'=>[],'posts'=>[['ref'=>'post:page:home','post'=>['post_type'=>'page','post_status'=>'publish','post_name'=>'home','post_title'=>'Home','post_content'=>'Original content','post_excerpt'=>''],'parent'=>0,'meta'=>[],'terms'=>[]]],'terms'=>[],'menus'=>[],'forms'=>[],'menu_locations'=>[],'files'=>[],'options'=>['blogname'=>'Optional '.$short,'blogdescription'=>'Voorstel','show_on_front'=>'page','page_on_front'=>['$ref'=>'post:page:home'],'page_for_posts'=>['$literal'=>0],'permalink_structure'=>'/%postname%/']];
