$reject(fn()=>Receiver::prepare($req($bad)),'Nonempty incomplete customer rejected');
$stored=Store::read('op-'.$op);$stored['status']='failed';$stored['error']='Projectmodel overschrijft gedeeld thema.';Store::write('op-'.$op,$stored);update_site_meta($id,'emsf_state','failed');
$recovered=Receiver::manage($req(['source'=>$source,'operation'=>$op,'action'=>'retry_models','confirm'=>get_blog_option($id,'blogname')]));
$check($recovered['operation']['status']==='complete'&&$recovered['customer']===[],'Legacy recovery succeeds without customer');
