$result=$run('user_create',$input);$first=(int)$result['customer']['id'];$check($first>0&&$result['users_saved'],'Create later and immediately designate');
$hash=get_userdata($first)->user_pass;
$input2=array_replace($input,['customer_name'=>'Second Person','customer_username'=>'second_'.$short,'customer_email'=>'second_'.$short.'@example.invalid','expected_customer_id'=>$first,'assign_customer'=>0]);
$result=$run('user_create',$input2);$users=$result['users'];$second=0;foreach($users as$u){if($u['id']!==$first){$second=$u['id'];}}
$check($second>0&&$result['customer']['id']===$first,'Create user without replacing customer');
$check(in_array('editor',(new WP_User($second,'',$id))->roles,true),'New site user receives editor role');
wp_set_current_user($first);Activity::record($id,'customer_front','first-session',$first);wp_set_current_user(1);$events=Activity::snapshot($id)['events'];
$run('customer_set',['expected_customer_id'=>$first,'customer_id'=>$second]);
$check(Accounts::details($id)['id']===$second&&is_user_member_of_blog($first,$id)&&get_userdata($first)->user_pass===$hash,'Switch preserves previous access and password');
$check(Activity::snapshot($id)['events']===$events&&end($events)['user_id']===$first,'History keeps original actor after switch');
$reject(fn()=>$run('customer_set',['expected_customer_id'=>$first,'customer_id'=>0]),'Stale customer form rejected');
$reject(fn()=>$run('customer_set',['expected_customer_id'=>$second,'customer_id'=>1]),'Superadmin cannot be designated');
$outsider=wpmu_create_user('outside_'.$short,'test-pass','outside_'.$short.'@example.invalid');
$reject(fn()=>$run('customer_set',['expected_customer_id'=>$second,'customer_id'=>$outsider]),'User of another site cannot be designated');
$reject(fn()=>$run('customer_set',['expected_customer_id'=>$second,'customer_id'=>-1]),'Malformed user identifier rejected');
$reject(fn()=>$run('setup_link',['expected_customer_id'=>$first]),'Stale mail cannot generate a link for new customer');
$fields=['draft_step'=>'follow','draft_first_name'=>'First','draft_company'=>'Fixture','draft_price'=>'100','draft_monthly'=>'10','draft_email'=>$input['customer_email'],'draft_include_backend'=>1,'draft_customer_id'=>$first];
$reject(fn()=>MailDraft::prepare($id,$fields),'Stale mail recipient blocked after switch');
$check(get_userdata($second)->user_activation_key==='','Rejected mail does not generate reset key');
$fields['draft_customer_id']=$second;$fields['draft_email']=$input2['customer_email'];$draft=MailDraft::prepare($id,$fields)['mail_draft'];
$check($draft['email']===$input2['customer_email']&&str_contains($draft['body'],'action=rp'),'Fresh mail uses current customer');
update_user_meta($second,'emsf_access_initialized',1);$key=get_userdata($second)->user_activation_key;MailDraft::prepare($id,$fields);
$check(get_userdata($second)->user_activation_key===$key,'Used account password setup key unchanged');
$replace=array_replace($payload,['action'=>'replace','operation'=>wp_generate_uuid4(),'confirm'=>get_blog_option($id,'blogname'),'expected_revision'=>ContentChanges::status($id)['token'],'replace_changes'=>true]);
Receiver::prepare($req($replace));Receiver::execute($req($replace));
$check(Accounts::details($id)['id']===$second&&Preview::details($id)['code']===$preview['code'],'Repush preserves changed customer and preview');
$run('customer_set',['expected_customer_id'=>$second,'customer_id'=>0]);
$check(Accounts::details($id)===[]&&is_user_member_of_blog($second,$id),'Clearing designation preserves access');
$fields['draft_customer_id']=0;$fields['draft_include_backend']=0;$draft=MailDraft::prepare($id,$fields)['mail_draft'];
$check(!str_contains($draft['body'],'wp-login')&&str_contains($draft['body'],$preview['code']),'Preview-only mail works without customer');
wp_set_current_user(0);$reject(fn()=>$run('users_get'),'Anonymous cannot list site accounts');wp_set_current_user(1);
update_site_meta($id,'emsf_state','importing');$reject(fn()=>$run('customer_set',['expected_customer_id'=>0,'customer_id'=>$first]),'Assignment blocked during publication');update_site_meta($id,'emsf_state','ready');
$_GET=['id'=>$id,'tab'=>'gebruikers'];ob_start();Admin::page();$html=ob_get_clean();
$check(str_contains($html,'Opdrachtgever opslaan')&&str_contains($html,'Gebruiker aanmaken')&&str_contains($html,'blijft gebruiker'),'Users UI contains selection, creation and access explanation');
$check($mail===0,'No account or publication mail sent');
file_put_contents(EMSF_STATE_DIR.'/users-ui.html','<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><style>body{font:16px system-ui;background:#f0f0f1;margin:24px}input,select,button{font:inherit;padding:8px}'.file_get_contents(dirname(__DIR__).'/assets/admin.css').'</style>'.$html.'<script>'.file_get_contents(dirname(__DIR__).'/assets/admin.js').'</script></html>');
echo "TOTAL: $n optional customer checks passed\n";
